const ORG_STAFF:Role[]=['comp_admin','head_judge','judge','ops_manager','exception_host','delegation_manager','broadcast_operator','auditor'];
const COMP_STAFF:Role[]=['head_judge','judge','ops_manager','exception_host','delegation_manager','broadcast_operator'];
const OWNER_STAFF:Role[]=['org_admin'];
const OPERATOR_STAFF:Role[]=['operator_owner','operator_admin'];
const roleHint=(r:Role|string,ar:boolean):string=>({
  operator_owner:ar?'السلطة الكاملة للمشغّل: يدير الجهات، ويدعو فريقه، ويعتمد ويوقف حساباتهم.':'Full operator authority: manages tenants, invites the team, approves and suspends accounts.',
  operator_admin:ar?'مساعد للمالك: يدير الجهات ويدعو، لكن لا يعتمد ولا يوقف الحسابات.':'Owner’s deputy: manages tenants and invites, but cannot approve or suspend accounts.',
  org_admin:ar?'صاحب الجهة: يبني مسابقاتها، ويدعو مديريها ومحكميها.':'Tenant owner: builds competitions and invites its admins and judges.',
  comp_admin:ar?'مدير مسابقة واحدة: يضبط إعداداتها وفريقها.':'Runs a single competition: its settings and team.',
  head_judge:ar?'رئيس التحكيم: يراجع الأحكام ويحسم الاستثناءات.':'Head judge: reviews scoring and resolves exceptions.',
  judge:ar?'محكّم: يقيّم داخل لجنته فقط.':'Judge: scores within their panel only.',
  support_agent:ar?'دعم فني بصلاحية محدودة عبر الجهات.':'Limited cross-tenant support access.',
} as Record<string,string>)[r]||'';
const arRole=(r:Role|string)=>({super_admin:'مدير المنصة',operator_owner:'مالك المشغّل',operator_admin:'مدير المشغّل',org_admin:'مدير الجهة',comp_admin:'مدير المسابقة',head_judge:'رئيس التحكيم',judge:'محكم',ops_manager:'مدير التشغيل',exception_host:'مكتب الاستثناء',delegation_manager:'مسؤول وفد',participant:'متسابق',broadcast_operator:'مشغل الحفل',auditor:'مدقق',guardian:'ولي أمر',support_agent:'دعم',storage_admin:'مدير التخزين',billing_admin:'مدير الفوترة',branch_admin:'مدير الفرع'} as Record<string,string>)[r]||String(r).replaceAll('_',' ');
type PasswordResetRow={id:string;organizationId:string;operatorId?:string;competitionId?:string;accountId:string;uid:string;email:string;displayName:string;reviewerRole:'org_admin'|'operator_owner'|'super_admin';status:'PENDING'|'ISSUED'|'USED'|'EXPIRED'|'REVOKED';requestedAt:string;requestExpiresAt:string;issuedAt?:string;linkExpiresAt?:string;usedAt?:string};
type RemoteData={accounts:any[];grants:any[];invitations:any[];sessions:any[];passwordResetRequests?:PasswordResetRow[]};
type AccessTab='grants'|'passwords'|'sessions'|'invite';
type ConfirmKind='suspend-account'|'resume-account'|'delete-account'|'delete-grant'|'delete-invitation'|'cancel-reset';
type ConfirmState={kind:ConfirmKind;account?:any;grant?:any;invitation?:any;reset?:PasswordResetRow;reason:string}|null;

export const activationQrValue=(token:string,origin?:string)=>{
 const base=(origin||window.location.origin).replace(/\/$/,'');
 const link=`${base}/#a=${encodeURIComponent(token)}`;
 return new TextEncoder().encode(link).length<=78?link:`MZI1|${token}`;
};

const dateText=(value:unknown,ar:boolean)=>{if(!value)return ar?'لا يوجد نشاط بعد':'No activity yet';const d=new Date(String(value));if(Number.isNaN(d.getTime()))return ar?'غير متاح':'Unavailable';return new Intl.DateTimeFormat(ar?'ar-KW-u-nu-latn':'en-GB',{dateStyle:'medium',timeStyle:'short'}).format(d)};
const inviteStatus=(status:string,ar:boolean)=>({READY:ar?'بانتظار التفعيل':'Awaiting activation',ACTIVATED:ar?'تم التفعيل':'Activated',EXPIRED:ar?'انتهت الدعوة':'Expired',REVOKED:ar?'ملغاة':'Revoked',PENDING_APPROVAL:ar?'بانتظار الاعتماد':'Awaiting approval'} as Record<string,string>)[status]||(ar?'حالة غير معروفة':'Unknown status');
const resetStatus=(status:string,ar:boolean)=>({PENDING:ar?'طلب جديد':'New request',ISSUED:ar?'تم إنشاء رابط':'Link issued',USED:ar?'تم تغيير كلمة المرور':'Password changed',EXPIRED:ar?'انتهت الصلاحية':'Expired',REVOKED:ar?'ملغى':'Revoked'} as Record<string,string>)[status]||(ar?'حالة غير معروفة':'Unknown status');
const identityHashParams=()=>{if(typeof window==='undefined'||!window.location.hash.startsWith('#identity'))return null;return new URLSearchParams(window.location.hash.split('?')[1]||'')};

export const IdentityGovernance:React.FC<{competitionId?:string;organizationId?:string;operatorId?:string;operatorName?:string}>=({competitionId,organizationId,operatorId,operatorName})=>{
 const s=useAppStore();const ar=s.language==='ar';const production=import.meta.env.VITE_REQUIRE_AUTH==='true';
 const operatorScoped=Boolean(operatorId);
 const operatorManagingOrganization=!operatorScoped&&Boolean(organizationId)&&['operator_owner','operator_admin'].includes(s.currentUser.role);
 const competitionScoped=Boolean(competitionId)&&!operatorScoped;
 const scopeOrgId=operatorScoped?`__operator__:${operatorId}`:(organizationId||s.currentUser.organizationId||s.organization.id);
 const operatorCanManage=s.currentUser.role==='super_admin'||s.currentUser.role==='operator_owner';
 const [tab,setTab]=useState<AccessTab>('grants');
 const [openAccountId,setOpenAccountId]=useState('');
 const [openSessionId,setOpenSessionId]=useState('');
 const [email,setEmail]=useState('');const [name,setName]=useState('');const [role,setRole]=useState<Role|''>('');
 const [message,setMessage]=useState('');const [oneTimeToken,setOneTimeToken]=useState('');const [oneTimeLabel,setOneTimeLabel]=useState('');
 const [remote,setRemote]=useState<RemoteData|null>(null);const [moduleGrants,setModuleGrants]=useState<string[]>([]);const [loading,setLoading]=useState(false);
 const [issuingReset,setIssuingReset]=useState('');const [issuedReset,setIssuedReset]=useState<{id:string;url:string;expiresAt?:string;displayName:string}|null>(null);
 const [editInvitation,setEditInvitation]=useState<any|null>(null);const [editInvitationName,setEditInvitationName]=useState('');const [editInvitationEmail,setEditInvitationEmail]=useState('');const [editInvitationRole,setEditInvitationRole]=useState<Role|''>('');
 const [editAccount,setEditAccount]=useState<any|null>(null);const [editAccountName,setEditAccountName]=useState('');
 const [editGrant,setEditGrant]=useState<{account:any;grant:any}|null>(null);const [editGrantRole,setEditGrantRole]=useState<Role|''>('');
 const [confirm,setConfirm]=useState<ConfirmState>(null);const [busyAction,setBusyAction]=useState('');const [focusedRequestId,setFocusedRequestId]=useState('');
 const say=useCallback((code:string)=>serverErrorLabel(code,ar),[ar]);
 const scopedCompetition=competitionId?s.competitions.find(c=>c.id===competitionId):undefined;
 const competitionClosed=Boolean(scopedCompetition&&['completed','archived'].includes(scopedCompetition.status));
 // Each level provisions only the owner of the level below; that owner then builds their own team.
 // Super admin therefore creates the operator OWNER only — the owner creates operator managers himself.
 const availableRoles=useMemo<Role[]>(()=>operatorScoped?(s.currentUser.role==='super_admin'?['operator_owner']:s.currentUser.role==='operator_owner'?['operator_admin']:[]):operatorManagingOrganization?['org_admin']:s.currentUser.role==='super_admin'?(competitionScoped?ORG_STAFF:OWNER_STAFF):s.currentUser.role==='comp_admin'?COMP_STAFF:ORG_STAFF,[s.currentUser.role,competitionScoped,operatorScoped,operatorManagingOrganization]);
 const effectiveRoles=competitionClosed?availableRoles.filter(r=>r==='auditor'):availableRoles;
 const identityProvisioningLocked=(operatorScoped&&!operatorCanManage)||(competitionClosed&&!effectiveRoles.length);
 const api=useCallback(async(path:string,init:RequestInit={})=>{const u=auth.currentUser;if(!u)throw new Error('IDENTITY_REQUIRED');const token=await u.getIdToken();return fetch(path,{...init,headers:{authorization:`Bearer ${token}`,'content-type':'application/json',...(init.headers||{})},cache:'no-store'})},[]);
 const request=useCallback(async(path:string,init:RequestInit={})=>{const r=await api(path,init);const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(String(body.code||'IDENTITY_ACTION_FAILED'));return body},[api]);
 const loadRemote=useCallback(async()=>{if(!production)return;setLoading(true);try{const params=new URLSearchParams();if(operatorScoped&&operatorId)params.set('operatorId',operatorId);else if(organizationId||s.currentUser.role==='super_admin')params.set('organizationId',scopeOrgId);if(competitionId&&!operatorScoped)params.set('competitionId',competitionId);const body=await request(`/api/identity/governance${params.size?`?${params}`:''}`);setRemote(body);setMessage('')}catch(e){setMessage(say(e instanceof Error?e.message:'IDENTITY_GOVERNANCE_UNAVAILABLE'));setRemote(null)}finally{setLoading(false)}},[production,s.currentUser.role,scopeOrgId,competitionId,operatorScoped,operatorId,organizationId,request,say]);
 const loadEntitlements=useCallback(async()=>{if(operatorScoped){setModuleGrants([]);return}if(!production){setModuleGrants(s.featureFlags.filter(f=>f.organizationId===scopeOrgId&&f.enabled).map(f=>f.key));return}try{const params=new URLSearchParams();if(s.currentUser.role==='super_admin')params.set('organizationId',scopeOrgId);const body=await request(`/api/identity/entitlements${params.size?`?${params}`:''}`);setModuleGrants(Array.isArray(body.licensedModules)?body.licensedModules.map(String):[])}catch{setModuleGrants([])}},[production,s.featureFlags,scopeOrgId,s.currentUser.role,operatorScoped,request]);
 useEffect(()=>{void loadRemote();void loadEntitlements()},[loadRemote,loadEntitlements]);
 useEffect(()=>{if(!production)return;const id=window.setInterval(()=>void loadRemote(),30_000);return()=>window.clearInterval(id)},[production,loadRemote]);
 useEffect(()=>{const apply=()=>{const q=identityHashParams();if(!q)return;const requestedTab=q.get('tab');if(requestedTab&&['grants','passwords','sessions','invite'].includes(requestedTab))setTab(requestedTab as AccessTab);setFocusedRequestId(q.get('requestId')||'')};apply();window.addEventListener('hashchange',apply);return()=>window.removeEventListener('hashchange',apply)},[]);

 const devGrants=useMemo(()=>operatorScoped?[]:s.roleGrants.filter(g=>g.organizationId===scopeOrgId&&['ACTIVE','SUSPENDED'].includes(g.status)&&(!competitionId||g.competitionId===competitionId)),[s.roleGrants,scopeOrgId,competitionId,operatorScoped]);
 const ids=useMemo(()=>new Set(devGrants.map(g=>g.accountId)),[devGrants]);
 const devAccounts=useMemo(()=>s.identityAccounts.filter(a=>a.organizationId===scopeOrgId&&ids.has(a.id)&&!s.roleGrants.some(g=>g.accountId===a.id&&g.role==='super_admin'&&g.status==='ACTIVE')),[s.identityAccounts,s.roleGrants,scopeOrgId,ids]);
 const accounts=production?(remote?.accounts||[]):devAccounts;
 const grants=production?(remote?.grants||[]):devGrants;
 const invitations=production?(remote?.invitations||[]):operatorScoped?[]:s.identityInvitations.filter(i=>i.organizationId===scopeOrgId&&i.status!=='REVOKED'&&(!competitionId||i.competitionId===competitionId));
 const sessions=production?(remote?.sessions||[]):operatorScoped?[]:s.authSessions.filter(x=>x.organizationId===scopeOrgId&&(!competitionId||(x as any).competitionId===competitionId));
 const passwordResetRequests:PasswordResetRow[]=production?(remote?.passwordResetRequests||[]):[];
 const activePasswordRequests=passwordResetRequests.filter(x=>x.status==='PENDING'||x.status==='ISSUED');
 const pendingInvitations=invitations.filter((x:any)=>x.status==='READY'||x.status==='PENDING_APPROVAL');
 const qrValue=oneTimeToken?activationQrValue(oneTimeToken):'';
 const activeSessions=sessions.filter((x:any)=>x.status==='ACTIVE');
 const accountForSession=(session:any)=>accounts.find((a:any)=>a.id===session.accountId);
 const grantForSession=(session:any)=>grants.find((g:any)=>g.accountId===session.accountId&&g.status==='ACTIVE'&&((session.competitionId&&g.competitionId===session.competitionId)||(!session.competitionId&&!g.competitionId)));
 const grantsFor=(account:any)=>grants.filter((g:any)=>g.accountId===account.id&&['ACTIVE','SUSPENDED'].includes(g.status));
 const lastSessionFor=(account:any)=>sessions.filter((x:any)=>x.accountId===account.id).sort((a:any,b:any)=>String(b.lastSeenAt||'').localeCompare(String(a.lastSeenAt||'')))[0];
 const isSelfAccount=(a:any)=>[a.id,a.uid,a.firebaseUid].filter(Boolean).includes(s.currentUser.id)||normalizeEmail(String(a.email||''))===normalizeEmail(s.currentUser.email||'');
 // The platform owner (super admin) can edit/remove every account except their own. Everyone else
 // keeps the scoped protections. Self-deletion is always blocked here and on the server.
 const isProtectedGrant=(a:any,g:any)=>operatorScoped?(isSelfAccount(a)||!(s.currentUser.role==='super_admin'||(s.currentUser.role==='operator_owner'&&g.role==='operator_admin'))):(s.currentUser.role==='super_admin'?isSelfAccount(a):isSelfAccount(a)||(g.role==='org_admin'&&!['operator_owner','operator_admin'].includes(s.currentUser.role)));
 const isProtectedAccount=(a:any)=>isSelfAccount(a)||grantsFor(a).some((g:any)=>isProtectedGrant(a,g));
 const roleChoicesForGrant=(g:any):Role[]=>operatorScoped?(s.currentUser.role==='super_admin'?OPERATOR_STAFF:['operator_admin']):operatorManagingOrganization?['org_admin']:effectiveRoles.length?effectiveRoles:[g.role];

 useEffect(()=>{if(!focusedRequestId||tab!=='passwords')return;const id=window.setTimeout(()=>document.getElementById(`password-reset-${focusedRequestId}`)?.scrollIntoView({behavior:'smooth',block:'center'}),100);return()=>window.clearTimeout(id)},[focusedRequestId,tab,remote]);
 useEffect(()=>{if(!production||!remote||!focusedRequestId)return;if(!passwordResetRequests.some(x=>x.id===focusedRequestId))setMessage(ar?'تعذر فتح الطلب المحدد: قد يكون حُذف، انتهى، أو لم تعد تملك صلاحية الوصول إليه.':'The requested item is unavailable, expired, or outside your access scope.')},[production,remote,focusedRequestId,passwordResetRequests,ar]);

 const create=async()=>{setMessage('');setOneTimeToken('');if(competitionClosed&&role!=='auditor')return setMessage(ar?'المسابقة منتهية؛ لا يمكن إنشاء صلاحيات تشغيلية جديدة. يمكن فقط إضافة مدقق للأرشيف.':'Competition is closed; only an archive auditor can be added.');const cleanEmail=normalizeEmail(email),cleanName=normalizeSpaces(name);if(!role||!isEmail(cleanEmail)||!cleanName)return setMessage(ar?'تحقق من الاسم والبريد والدور.':'Check name, email and role.');if(operatorScoped&&!operatorCanManage)return setMessage(ar?'لا تملك صلاحية إدارة حسابات هذا المشغّل.':'You cannot manage this operator.');if(production){try{if(!operatorScoped&&!operatorManagingOrganization&&s.currentUser.role!=='super_admin'&&!competitionId)return setMessage(say('COMPETITION_SCOPE_REQUIRED'));const body=await request('/api/identity/invitations',{method:'POST',body:JSON.stringify({email:cleanEmail,displayName:cleanName,requestedRole:role,operatorId:operatorScoped?operatorId:undefined,organizationId:(!operatorScoped&&(s.currentUser.role==='super_admin'||operatorManagingOrganization))?scopeOrgId:undefined,competitionId:competitionScoped?competitionId:undefined,reason:operatorScoped?'Authorized operator access provisioning':operatorManagingOrganization?'Authorized operator-managed organization owner provisioning':'Authorized scoped role provisioning'})});setEmail('');setName('');setRole('');if(body.activationToken){setOneTimeToken(String(body.activationToken));setOneTimeLabel(cleanName)}setMessage(ar?'تم إنشاء الدعوة. يظهر الحساب الآن بوضوح كـ «بانتظار التفعيل» إلى أن يستخدم صاحبه رمز QR.':'Invitation created and shown as awaiting activation until the QR is used.');setTab('grants');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'IDENTITY_SERVER_UNAVAILABLE'))}return}if(operatorScoped||operatorManagingOrganization)return setMessage(ar?'إدارة هذا النطاق تحتاج خادم الهوية المفعّل.':'This access scope requires the identity server.');if(!competitionId)return setMessage(say('COMPETITION_SCOPE_REQUIRED'));const out=await s.createIdentityInvitation({email:cleanEmail,displayName:cleanName,requestedRole:role,competitionId,reason:'Authorized competition role provisioning'});if(!out.ok)return setMessage(say(String(out.reason)));if(out.activationToken){setOneTimeToken(out.activationToken);setOneTimeLabel(cleanName)}};
 const grantToggle=async(grant:any)=>{if(!production){const resume=grant.status==='SUSPENDED';s.setRoleGrantStatus(grant.id,resume?'ACTIVE':'SUSPENDED');setMessage(resume?(ar?'أُعيدت الصلاحية.':'Access restored.'):(ar?'جُمّدت الصلاحية.':'Access frozen.'));return}const resume=grant.status==='SUSPENDED';setBusyAction(`grant-toggle-${grant.id}`);try{await request(`/api/identity/grants/${encodeURIComponent(grant.id)}/${resume?'resume':'suspend'}`,{method:'POST',body:JSON.stringify({reason:resume?'Authorized scoped access restored':'Authorized scoped access frozen'})});setMessage(resume?(ar?'أُعيدت الصلاحية.':'Access restored.'):(ar?'جُمّدت الصلاحية وأُغلقت جلساتها النشطة.':'Access frozen and active sessions closed.'));await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'ACCESS_CHANGE_FAILED'))}finally{setBusyAction('')}};
 const reissueGrant=async(grant:any)=>{if(!production){const out=await s.reissueIdentityInvitation(grant.id);setMessage(out.ok?(ar?'أُصدر رمز تفعيل جديد.':'New activation QR issued.'):(ar?'الصلاحية مفعّلة بالفعل ولا تحتاج رمزًا جديدًا.':'Grant is already active.'));return}setBusyAction(`grant-qr-${grant.id}`);setOneTimeToken('');try{const body=await request(`/api/identity/grants/${encodeURIComponent(grant.id)}/reissue-qr`,{method:'POST',body:'{}'});setOneTimeToken(String(body.activationToken||''));setOneTimeLabel(ar?'إعادة تفعيل المستخدم':'User reactivation');setMessage(ar?'أُلغي أي رمز تفعيل سابق وصدر رمز جديد لمرة واحدة.':'Previous activation QR invalidated and a new one issued.');setTab('invite');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'QR_REISSUE_FAILED'))}finally{setBusyAction('')}};
 const revokeGrantSessions=async(grant:any)=>{if(!production){s.setRoleGrantStatus(grant.id,grant.status);setMessage(ar?'أُغلقت الجلسات النشطة لهذه الصلاحية.':'Active sessions for this grant closed.');return}setBusyAction(`grant-session-${grant.id}`);try{const body=await request(`/api/identity/grants/${encodeURIComponent(grant.id)}/revoke-sessions`,{method:'POST',body:JSON.stringify({reason:'Authorized secure session closure'})});setMessage(ar?`أُغلقت ${body.count||0} جلسة نشطة.`:`${body.count||0} active session(s) closed.`);await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'SESSION_REVOKE_FAILED'))}finally{setBusyAction('')}};
 const revokeAccountSessions=async(account:any)=>{if(!production){setMessage(ar?'أُغلقت جلسات الحساب النشطة.':'Active account sessions closed.');return}setBusyAction(`account-session-${account.id}`);try{const body=await request(`/api/identity/accounts/${encodeURIComponent(account.id)}/revoke-sessions`,{method:'POST',body:JSON.stringify({reason:'Authorized account session closure'})});setMessage(ar?`أُغلقت ${body.count||0} جلسة للحساب.`:`${body.count||0} account session(s) closed.`);await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'SESSION_REVOKE_FAILED'))}finally{setBusyAction('')}};
 const copyActivation=async()=>{try{await navigator.clipboard.writeText(qrValue);setMessage(ar?'تم نسخ رابط التفعيل.':'Activation link copied.')}catch{setMessage(ar?'تعذر النسخ؛ استخدم رمز QR.':'Copy failed; use the QR.')}};
 const issuePasswordReset=async(row:PasswordResetRow)=>{if(!production)return;setIssuingReset(row.id);setMessage('');try{const body=await request(`/api/identity/password-reset/${encodeURIComponent(row.id)}/issue`,{method:'POST',body:'{}'});setIssuedReset({id:row.id,url:String(body.resetUrl||''),expiresAt:String(body.expiresAt||''),displayName:row.displayName});setMessage(ar?'تم إنشاء رابط آمن لمرة واحدة. شاركه مع صاحب الحساب فقط؛ لا يستطيع المدير رؤية كلمة المرور الجديدة.':'A one-time secure link is ready. Share it only with the account owner.');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'PASSWORD_RESET_LINK_UNAVAILABLE'))}finally{setIssuingReset('')}};
 const copyReset=async()=>{if(!issuedReset?.url)return;try{await navigator.clipboard.writeText(issuedReset.url);setMessage(ar?'تم نسخ رابط تغيير كلمة المرور.':'Password reset link copied.')}catch{setMessage(ar?'تعذر النسخ؛ اعرض رمز QR للمستخدم.':'Copy failed; show the QR to the user.')}};

 const openEditInvitation=(i:any)=>{setEditInvitation(i);setEditInvitationName(i.displayName||'');setEditInvitationEmail(i.email||'');setEditInvitationRole(i.requestedRole||'')};
 const saveInvitation=async()=>{if(!editInvitation)return;const cleanName=normalizeSpaces(editInvitationName),cleanEmail=normalizeEmail(editInvitationEmail);if(!cleanName||!isEmail(cleanEmail)||!editInvitationRole)return setMessage(ar?'تحقق من الاسم والبريد والدور.':'Check name, email and role.');if(!production){s.updateIdentityInvitationDetails(editInvitation.id,{displayName:cleanName,email:cleanEmail,requestedRole:editInvitationRole as Role});setEditInvitation(null);setMessage(ar?'تم تعديل الدعوة المعلّقة.':'Pending invitation updated.');return}setBusyAction(`inv-edit-${editInvitation.id}`);try{await request(`/api/identity/invitations/${encodeURIComponent(editInvitation.id)}`,{method:'PATCH',body:JSON.stringify({displayName:cleanName,email:cleanEmail,requestedRole:editInvitationRole})});setEditInvitation(null);setMessage(ar?'تم تعديل الدعوة المعلّقة.':'Pending invitation updated.');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'INVITATION_UPDATE_FAILED'))}finally{setBusyAction('')}};
 const reissueInvitation=async(i:any)=>{if(!production){const out=await s.reissueIdentityInvitation(i.id);if(out.ok){setOneTimeToken(out.activationToken);setOneTimeLabel(i.displayName||'');setTab('invite');setMessage(ar?'تم إصدار QR جديد صالح لمرة واحدة.':'A new one-time activation QR was issued.')}else setMessage(say(String(out.reason)));return}setBusyAction(`inv-qr-${i.id}`);try{const body=await request(`/api/identity/invitations/${encodeURIComponent(i.id)}/reissue`,{method:'POST',body:'{}'});setOneTimeToken(String(body.activationToken||''));setOneTimeLabel(i.displayName||'');setTab('invite');setMessage(ar?'تم إلغاء رمز الدعوة السابق وإصدار QR جديد صالح لمرة واحدة.':'A new one-time activation QR was issued.');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'INVITATION_REISSUE_FAILED'))}finally{setBusyAction('')}};
 const approveInvitation=async(i:any)=>{if(!production){const out=await s.approveIdentityInvitation(i.id);if(out.ok){setOneTimeToken(out.activationToken);setOneTimeLabel(i.displayName||'');setTab('invite');setMessage(ar?'تم اعتماد الدعوة وإصدار QR التفعيل.':'Invitation approved and activation QR issued.')}else setMessage(say(String(out.reason)));return}setBusyAction(`inv-approve-${i.id}`);try{const body=await request(`/api/identity/invitations/${encodeURIComponent(i.id)}/approve`,{method:'POST',body:'{}'});setOneTimeToken(String(body.activationToken||''));setOneTimeLabel(i.displayName||'');setTab('invite');setMessage(ar?'تم اعتماد الدعوة وإصدار QR التفعيل.':'Invitation approved and activation QR issued.');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'APPROVAL_FAILED'))}finally{setBusyAction('')}};
 const openEditAccount=(a:any)=>{setEditAccount(a);setEditAccountName(a.displayName||'')};
 const saveAccount=async()=>{if(!editAccount)return;const cleanName=normalizeSpaces(editAccountName);if(!cleanName)return;if(!production){s.updateIdentityAccountName(editAccount.id,cleanName);setEditAccount(null);setMessage(ar?'تم تحديث بيانات الحساب.':'Account details updated.');return}setBusyAction(`account-edit-${editAccount.id}`);try{await request(`/api/identity/accounts/${encodeURIComponent(editAccount.id)}`,{method:'PATCH',body:JSON.stringify({displayName:cleanName})});setEditAccount(null);setMessage(ar?'تم تحديث بيانات الحساب.':'Account details updated.');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'ACCOUNT_UPDATE_FAILED'))}finally{setBusyAction('')}};
 const openEditGrant=(account:any,grant:any)=>{setEditGrant({account,grant});setEditGrantRole(grant.role)};
 const saveGrant=async()=>{if(!editGrant||!editGrantRole)return;if(!production){s.updateRoleGrantRole(editGrant.grant.id,editGrantRole as Role);setEditGrant(null);setMessage(ar?'تم تعديل الدور.':'Role updated.');return}setBusyAction(`grant-edit-${editGrant.grant.id}`);try{await request(`/api/identity/grants/${encodeURIComponent(editGrant.grant.id)}`,{method:'PATCH',body:JSON.stringify({role:editGrantRole,reason:'Authorized role update from identity governance'})});setEditGrant(null);setMessage(ar?'تم تعديل الدور وإغلاق الجلسات القديمة المرتبطة به احترازيًا.':'Role updated; old scoped sessions were closed for safety.');await loadRemote()}catch(e){setMessage(say(e instanceof Error?e.message:'GRANT_UPDATE_FAILED'))}finally{setBusyAction('')}};
 const runConfirm=async()=>{if(!confirm||confirm.reason.trim().length<5)return;const key=confirm.kind;
  if(!production){let done=true;
   if(key==='suspend-account'&&confirm.account)done=s.suspendIdentityAccount(confirm.account.id,confirm.reason);
   else if(key==='resume-account'&&confirm.account)done=s.resumeIdentityAccount(confirm.account.id);
   else if(key==='delete-account'&&confirm.account)done=s.removeIdentityAccount(confirm.account.id,confirm.reason);
   else if(key==='delete-grant'&&confirm.grant)done=s.removeRoleGrant(confirm.grant.id,confirm.reason);
   else if(key==='delete-invitation'&&confirm.invitation)done=s.deleteIdentityInvitation(confirm.invitation.id);
   else if(key==='cancel-reset')done=true;
   const okMsg:Record<ConfirmKind,string>={'suspend-account':ar?'تم إيقاف الحساب.':'Account suspended.','resume-account':ar?'تمت إعادة تفعيل الحساب.':'Account restored.','delete-account':ar?'أُلغي وصول الحساب.':'Account access removed.','delete-grant':ar?'أُلغيت هذه الصلاحية.':'Grant removed.','delete-invitation':ar?'أُلغيت الدعوة.':'Invitation cancelled.','cancel-reset':ar?'أُلغي الطلب.':'Request cancelled.'};
   setMessage(done?okMsg[key]:(ar?'تعذّر تنفيذ الإجراء على هذا العنصر.':'Could not apply the action to this item.'));if(done)setConfirm(null);return}
  setBusyAction(`confirm-${key}`);try{
  if(key==='suspend-account'&&confirm.account)await request(`/api/identity/accounts/${encodeURIComponent(confirm.account.id)}/suspend`,{method:'POST',body:JSON.stringify({reason:confirm.reason})});
  if(key==='resume-account'&&confirm.account)await request(`/api/identity/accounts/${encodeURIComponent(confirm.account.id)}/resume`,{method:'POST',body:JSON.stringify({reason:confirm.reason})});
  if(key==='delete-account'&&confirm.account)await request(`/api/identity/accounts/${encodeURIComponent(confirm.account.id)}`,{method:'DELETE',body:JSON.stringify({reason:confirm.reason})});
  if(key==='delete-grant'&&confirm.grant)await request(`/api/identity/grants/${encodeURIComponent(confirm.grant.id)}`,{method:'DELETE',body:JSON.stringify({reason:confirm.reason})});
  if(key==='delete-invitation'&&confirm.invitation)await request(`/api/identity/invitations/${encodeURIComponent(confirm.invitation.id)}`,{method:'DELETE',body:JSON.stringify({reason:confirm.reason})});
  if(key==='cancel-reset'&&confirm.reset)await request(`/api/identity/password-reset/${encodeURIComponent(confirm.reset.id)}`,{method:'DELETE',body:JSON.stringify({reason:confirm.reason})});
  const ok:Record<ConfirmKind,string>={
   'suspend-account':ar?'تم إيقاف الحساب وكل صلاحياته وإغلاق جلساته.':'Account suspended with all grants and sessions closed.',
   'resume-account':ar?'تمت إعادة تفعيل الحساب والصلاحيات المسموح بإعادتها.':'Account access restored.',
   'delete-account':ar?'أُلغي وصول الحساب بالكامل مع إبقاء أثره في سجل التدقيق.':'Account access removed while audit history was preserved.',
   'delete-grant':ar?'أُلغيت هذه الصلاحية فقط وبقيت بقية صلاحيات المستخدم.':'Only this grant was removed.',
   'delete-invitation':ar?'أُلغيت الدعوة ولم يعد رمز التفعيل صالحًا.':'Invitation revoked and its activation token invalidated.',
   'cancel-reset':ar?'أُلغي طلب تغيير كلمة المرور وأصبح أي رابط صادر عنه غير صالح.':'Password-reset request revoked.',
  };
  setMessage(ok[key]);setConfirm(null);await loadRemote();
 }catch(e){setMessage(say(e instanceof Error?e.message:'IDENTITY_ACTION_FAILED'))}finally{setBusyAction('')}};

 const tabs:[AccessTab,string,string][]=[
  ['grants',ar?'الفريق والصلاحيات':'Team & grants',String(accounts.length+pendingInvitations.length)],
  ['passwords',ar?'طلبات كلمة المرور':'Password requests',String(activePasswordRequests.length)],
  ['sessions',ar?'الجلسات':'Sessions',String(activeSessions.length)],
  ...(operatorScoped&&!operatorCanManage?[]:[['invite',ar?'إضافة مستخدم':'Invite user','+'] as [AccessTab,string,string]]),
 ];
 const confirmTitle=confirm?({
  'suspend-account':ar?'إيقاف الحساب بالكامل':'Suspend account',
  'resume-account':ar?'إعادة تفعيل الحساب':'Restore account',
  'delete-account':ar?'حذف وصول الحساب':'Remove account access',
  'delete-grant':ar?'إلغاء الصلاحية':'Remove grant',
  'delete-invitation':ar?'إلغاء الدعوة':'Cancel invitation',
  'cancel-reset':ar?'إلغاء طلب كلمة المرور':'Cancel password request',
 } as Record<ConfirmKind,string>)[confirm.kind]:'';

 return <section className="mizan-surface p-4 sm:p-5 overflow-hidden">
  <div className="flex flex-col lg:flex-row lg:items-start justify-between gap-4">
   <div><div className="mizan-kicker">{ar?'الهوية والصلاحيات':'IDENTITY & ACCESS'}</div><h2 className="text-lg sm:text-xl font-black mt-1">{operatorScoped?(ar?`دخول وصلاحيات ${operatorName||'المشغّل'}`:`${operatorName||'Operator'} access`):competitionScoped?(ar?'فريق هذه المسابقة':'This competition team'):(ar?'حسابات هذه الجهة وصلاحياتها':'Organization accounts and access')}</h2><p className="text-[11px] leading-5 text-[#636864] mt-2 max-w-2xl">{ar?'الحسابات والدعوات والأدوار والجلسات وطلبات كلمة المرور قابلة للإدارة من هنا، وكل إجراء حساس يفرضه الخادم ويُسجَّل تدقيقيًا.':'Accounts, invitations, roles, sessions and password requests are managed here with server-enforced, audited actions.'}</p></div>
   <div className="grid grid-cols-3 gap-2 min-w-0 sm:min-w-64"><Mini n={accounts.length} t={ar?'حسابات':'Accounts'}/><Mini n={pendingInvitations.length} t={ar?'بانتظار التفعيل':'Pending'}/><Mini n={activePasswordRequests.length} t={ar?'طلبات كلمة مرور':'Password'}/></div>
  </div>
  {activePasswordRequests.length>0&&<button type="button" onClick={()=>setTab('passwords')} className="mt-4 w-full rounded-2xl border border-[#d8c7a7] bg-[#fbf5e8] px-4 py-3 flex items-center gap-3 text-start"><BellRing className="w-5 h-5 text-[#7a5a2f] shrink-0"/><div className="flex-1"><div className="text-xs font-black text-[#604724]">{ar?`${activePasswordRequests.length} طلب تغيير كلمة مرور يحتاج إجراءً`:`${activePasswordRequests.length} password request(s) need attention`}</div><div className="text-[10px] leading-5 text-[#6b5b45] mt-1">{ar?'اضغط لفتح الطلبات مباشرة؛ كل طلب مستقل ويمكن إصدار رابط أو إلغاؤه.':'Open the exact request to issue or revoke its one-time reset link.'}</div></div></button>}
  {competitionClosed&&<div className="mt-4 rounded-xl border border-[#d8c7a7] bg-[#fbf5e8] px-4 py-3 flex items-start gap-3"><LockKeyhole className="w-4 h-4 text-[#7a5a2f] shrink-0 mt-0.5"/><div><div className="text-xs font-black text-[#604724]">{ar?'المسابقة منتهية — الوصول التشغيلي مقفول':'Competition closed — operational access locked'}</div><p className="text-[10px] leading-5 text-[#6b5b45] mt-1">{ar?'تبقى الحسابات والسجلات مرئية للإدارة والتدقيق، ويمكن إضافة مدقق أرشيفي فقط عند الحاجة.':'Accounts remain visible for administration and audit.'}</p></div></div>}
  <div className="mizan-tabs mt-4" role="tablist">{tabs.map(([id,label,count])=><button key={id} role="tab" aria-selected={tab===id} onClick={()=>setTab(id)} className={`mizan-tab ${tab===id?'is-active':''}`}><span>{label}</span><span className={`rounded-full px-1.5 py-.5 text-[9px] ${tab===id?'bg-white/15':'bg-[#f1efe9]'}`}>{count}</span></button>)}</div>
  {message&&<div role="status" className="mt-3 rounded-xl bg-[#f3f1eb] p-3 text-xs font-bold break-words">{message}</div>}

  {tab==='grants'&&<div className="mt-4 space-y-4">
   {!competitionScoped&&!operatorScoped&&<div className="rounded-2xl border border-[#dfddd6] p-4"><div className="flex items-center gap-2"><Layers3 className="w-4 h-4 text-[#2F6555]"/><div className="text-sm font-black">{ar?'صلاحيات المنصة الممنوحة للجهة':'Platform entitlements'}</div></div>{moduleGrants.length?<div className="mt-3 flex flex-wrap gap-2">{moduleGrants.map(key=><Badge key={key} variant="emerald">{featureLabel(key,ar)}</Badge>)}</div>:<p className="mt-3 text-[11px] text-[#696f6b]">{ar?'لا توجد وحدات إضافية مرخصة حاليًا. حسابات المستخدمين الفعلية تظهر أدناه.':'No additional modules are licensed. User accounts appear below.'}</p>}</div>}

   {pendingInvitations.length>0&&<div className="rounded-2xl border border-[#d8c7a7] bg-[#fffaf0] overflow-hidden">
    <div className="px-4 py-3 border-b border-[#e9dcc3]"><div className="text-sm font-black">{ar?'حسابات أُضيفت ولم تُفعّل بعد':'Added accounts awaiting activation'}</div><p className="text-[10px] text-[#6b5b45] mt-1">{ar?'يمكن تعديل الاسم والبريد والدور قبل التفعيل، وإعادة إصدار QR أو إلغاء الدعوة نهائيًا.':'Edit pending identity details, reissue the QR, or revoke the invitation.'}</p></div>
    <div className="divide-y divide-[#eee2cb]">{pendingInvitations.map((i:any)=><div key={i.id} className="p-4 flex flex-col lg:flex-row lg:items-center gap-3">
     <div className="flex-1 min-w-0"><div className="font-black text-sm">{i.displayName}</div><div dir="ltr" className="text-[11px] text-[#656b66] break-all">{i.email}</div><div className="mt-2 flex flex-wrap gap-2"><Badge variant="amber">{inviteStatus(i.status,ar)}</Badge><Badge variant="neutral">{ar?arRole(i.requestedRole):String(i.requestedRole).replaceAll('_',' ')}</Badge></div></div>
     <div className="text-[10px] text-[#656b66] lg:text-end"><div>{ar?'أُضيف في':'Added'}</div><div className="mt-1">{dateText(i.createdAt,ar)}</div></div>
     {<div className="flex flex-wrap gap-2"><IconButton title={ar?'تعديل الدعوة':'Edit invitation'} onClick={()=>openEditInvitation(i)}><Pencil className="w-4 h-4"/></IconButton>{i.status==='PENDING_APPROVAL'?<IconButton title={ar?'اعتماد الدعوة وإصدار QR':'Approve & issue QR'} onClick={()=>void approveInvitation(i)}><CheckCircle2 className="w-4 h-4"/></IconButton>:<IconButton title={ar?'إصدار QR جديد':'Reissue QR'} onClick={()=>void reissueInvitation(i)}><QrCode className="w-4 h-4"/></IconButton>}<IconButton danger title={ar?'إلغاء الدعوة':'Cancel invitation'} onClick={()=>setConfirm({kind:'delete-invitation',invitation:i,reason:ar?'إلغاء الدعوة المعلّقة بناءً على قرار المسؤول':'Cancel pending invitation by authorized administrator'})}><Trash2 className="w-4 h-4"/></IconButton></div>}
    </div>)}</div>
   </div>}

   {/* مئة حساب في قائمةٍ مفتوحة تعني تمريرًا لا ينتهي. البطاقة تعرض الاسم وحالته فقط،
        وتُفتح بالنقر على ما تحتها: الصلاحيات والجلسات والأزرار. شبكةٌ لا طابور. */}
   <div className="grid sm:grid-cols-2 xl:grid-cols-3 gap-3 items-start">{accounts.map((a:any)=>{const last=lastSessionFor(a),accountGrants=grantsFor(a),protectedAccount=isProtectedAccount(a),expanded=openAccountId===a.id;return <div key={a.id} className={`rounded-2xl border p-4 transition ${expanded?'border-[#b9ccc3] bg-[#F7FAF8] sm:col-span-2 xl:col-span-3':'border-[#e5e3dc] bg-white'}`}>
     <button type="button" onClick={()=>setOpenAccountId(expanded?'':a.id)} aria-expanded={expanded} className="w-full flex items-center justify-between gap-3 text-start">
      <span className="min-w-0"><span className="block font-black text-sm truncate">{a.displayName}</span><span className="mt-1 flex flex-wrap items-center gap-1.5"><Badge variant={a.status==='ACTIVE'?'emerald':'amber'}>{a.status==='ACTIVE'?(ar?'نشط':'Active'):(ar?'موقوف':'Suspended')}</Badge>{last&&last.status==='ACTIVE'&&<Badge variant="emerald">{ar?'جلسة نشطة':'Session'}</Badge>}{accountGrants.length>0&&<span className="text-[11px] font-bold text-[#656b66]">{accountGrants.map((g:any)=>ar?arRole(g.role):String(g.role).replaceAll('_',' ')).join(' · ')}</span>}</span></span>
      <ChevronDown className={`w-5 h-5 shrink-0 text-[#66706a] transition ${expanded?'rotate-180':''}`}/>
     </button>
     {expanded&&<div className="mt-4 pt-4 border-t border-[#dfe5e1]">
      <div className="flex flex-col xl:flex-row xl:items-start justify-between gap-3">
       <div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><div className="font-black text-sm">{a.displayName}</div>{protectedAccount&&<Badge variant="neutral">{ar?'هوية محمية':'Protected identity'}</Badge>}</div><div dir="ltr" className="text-[11px] text-[#656b66] break-all">{a.email}</div><div className="mt-2 flex flex-wrap gap-2"><Badge variant={a.status==='ACTIVE'?'emerald':'amber'}>{a.status==='ACTIVE'?(ar?'الحساب نشط':'Account active'):(ar?'الحساب موقوف':'Account suspended')}</Badge>{last&&<Badge variant={last.status==='ACTIVE'?'emerald':'neutral'}>{last.status==='ACTIVE'?(ar?'جلسة نشطة':'Active session'):(ar?'لا توجد جلسة نشطة':'No active session')}</Badge>}</div></div>
     <div className="flex flex-wrap items-center gap-2"><div className="rounded-xl bg-[#f7f5ef] px-3 py-2 text-[10px] text-[#656b66] xl:text-end"><div>{ar?'آخر نشاط':'Last activity'}</div><div className="font-bold text-[#414944] mt-1">{dateText(last?.lastSeenAt,ar)}</div></div>{!protectedAccount&&(accountGrants.length===1?
      /* Single-grant account: the per-grant row below already exposes edit/freeze/sessions/delete,
         so we only keep the name edit here to avoid the duplicated icon cluster. */
      <IconButton title={ar?'تعديل اسم الحساب':'Edit account name'} onClick={()=>openEditAccount(a)}><Pencil className="w-4 h-4"/></IconButton>
      :<><IconButton title={ar?'تعديل بيانات الحساب':'Edit account'} onClick={()=>openEditAccount(a)}><Pencil className="w-4 h-4"/></IconButton><IconButton title={ar?'إغلاق كل جلسات الحساب':'Close all account sessions'} onClick={()=>void revokeAccountSessions(a)}><Laptop2 className="w-4 h-4"/></IconButton>{a.status==='ACTIVE'?<IconButton title={ar?'إيقاف الحساب وكل صلاحياته':'Suspend whole account'} onClick={()=>setConfirm({kind:'suspend-account',account:a,reason:ar?'إيقاف الحساب مؤقتًا بناءً على قرار المسؤول':'Temporarily suspend account by authorized administrator'})}><Pause className="w-4 h-4"/></IconButton>:<IconButton title={ar?'إعادة تفعيل الحساب':'Restore account'} onClick={()=>setConfirm({kind:'resume-account',account:a,reason:ar?'إعادة تفعيل الحساب بناءً على قرار المسؤول':'Restore account by authorized administrator'})}><RotateCcw className="w-4 h-4"/></IconButton>}<IconButton danger title={ar?'حذف وصول الحساب بالكامل':'Remove account access'} onClick={()=>setConfirm({kind:'delete-account',account:a,reason:ar?'إلغاء وصول الحساب بالكامل بناءً على قرار المسؤول':'Remove account access by authorized administrator'})}><Trash2 className="w-4 h-4"/></IconButton></>)}</div>
    </div>
    <div className="mt-3 space-y-2">{accountGrants.map((g:any)=>{const protectedGrant=isProtectedGrant(a,g),choices=roleChoicesForGrant(g);return <div key={g.id} className="rounded-xl bg-[#f7f5ef] p-3 flex flex-wrap items-center gap-2">
     <div className="flex-1 min-w-[180px]"><div className="text-xs font-black">{ar?arRole(g.role):String(g.role).replaceAll('_',' ')}</div><div className="text-[10px] text-[#656b66] mt-1">{operatorScoped?(ar?'صلاحية على مستوى المشغّل':'Operator-level access'):g.competitionId?(ar?'صلاحية خاصة بالمسابقة الحالية':'Competition-scoped access'):(ar?'صلاحية على مستوى الجهة':'Organization-level access')}</div></div><Badge variant={g.status==='ACTIVE'?'emerald':'amber'}>{g.status==='ACTIVE'?(ar?'نشطة':'Active'):(ar?'مجمّدة':'Frozen')}</Badge>
     {protectedGrant?<div className="min-h-11 px-3 rounded-xl border border-[#d9dfdb] inline-flex items-center gap-2 text-[10px] font-black text-[#59615c]" title={ar?'هذه الهوية محمية من التعديل الذاتي أو من كسر استمرارية الإدارة.':'Protected identity'}><LockKeyhole className="w-4 h-4"/>{ar?'محمي':'Protected'}</div>:<>{choices.some(r=>r!==g.role)&&<IconButton title={ar?'تعديل الدور والصلاحية':'Edit role'} onClick={()=>openEditGrant(a,g)}><Pencil className="w-4 h-4"/></IconButton>}<IconButton title={g.status==='ACTIVE'?(ar?'تجميد الصلاحية':'Freeze access'):(ar?'إعادة الصلاحية':'Restore access')} onClick={()=>void grantToggle(g)}>{g.status==='ACTIVE'?<Pause className="w-4 h-4"/>:<Play className="w-4 h-4"/>}</IconButton>{g.status==='ACTIVE'&&<IconButton title={ar?'إصدار QR تفعيل جديد':'Reissue activation QR'} onClick={()=>void reissueGrant(g)}><QrCode className="w-4 h-4"/></IconButton>}<IconButton title={ar?'إغلاق جلسات هذه الصلاحية':'Close scoped sessions'} onClick={()=>void revokeGrantSessions(g)}><Laptop2 className="w-4 h-4"/></IconButton><IconButton danger title={ar?'حذف هذه الصلاحية':'Remove grant'} onClick={()=>setConfirm({kind:'delete-grant',account:a,grant:g,reason:ar?'إلغاء هذه الصلاحية المحددة بناءً على قرار المسؤول':'Remove scoped grant by authorized administrator'})}><Trash2 className="w-4 h-4"/></IconButton></>}
    </div>})}</div>
   </div>}</div>})}{!accounts.length&&!pendingInvitations.length&&<div className="py-8 text-center text-xs text-[#696f6b]">{loading?(ar?'جارٍ تحميل الحسابات…':'Loading accounts…'):(operatorScoped?(ar?'لا توجد حسابات أو دعوات لهذا المشغّل بعد.':'No accounts or invitations exist for this operator yet.'):(ar?'لا توجد حسابات أو دعوات في هذه الجهة بعد.':'No accounts or invitations exist yet.'))}</div>}</div>
  </div>}

  {tab==='passwords'&&<div className="mt-4 space-y-4">
   <div className="rounded-2xl border border-[#d7e1dc] bg-[#f7faf8] p-4"><div className="flex items-start gap-3"><ShieldCheck className="w-5 h-5 text-[#2F6555] shrink-0 mt-0.5"/><div><div className="text-sm font-black">{ar?'استعادة كلمة المرور بموافقة المسؤول':'Administrator-mediated password recovery'}</div><p className="text-[11px] leading-6 text-[#5d645f] mt-1">{ar?'كل طلب يظهر مستقلًا. يمكنك إنشاء رابط آمن لمرة واحدة أو إلغاء الطلب؛ الضغط من الإشعار يفتح الطلب نفسه مباشرة.':'Each request is independent: issue a one-time link or revoke it. Notification deep links open the exact request.'}</p></div></div></div>
   {issuedReset&&<div className="rounded-2xl border border-[#cfded6] bg-[#f5faf7] p-4"><div className="flex items-center gap-2"><CheckCircle2 className="w-5 h-5 text-[#2F6555]"/><div><div className="text-sm font-black">{ar?`رابط جديد لـ ${issuedReset.displayName}`:`New link for ${issuedReset.displayName}`}</div><div className="text-[10px] text-[#656b66] mt-1">{ar?`صالح لمرة واحدة حتى ${dateText(issuedReset.expiresAt,ar)}.`:`One-time link valid until ${dateText(issuedReset.expiresAt,ar)}.`}</div></div></div><div className="mt-4 flex justify-center"><div className="rounded-2xl bg-white p-3 border"><RealQRCode value={issuedReset.url} size={184}/></div></div><div className="mt-3 rounded-xl bg-white border p-3 text-[10px] break-all" dir="ltr">{issuedReset.url}</div><Button className="mt-3 w-full" variant="outline" onClick={()=>void copyReset()} icon={<Copy className="w-4 h-4"/>}>{ar?'نسخ الرابط الآمن':'Copy secure link'}</Button></div>}
   <div className="rounded-2xl border border-[#dfddd6] overflow-hidden"><div className="divide-y divide-[#e5e3dc]">{passwordResetRequests.map(req=><div id={`password-reset-${req.id}`} key={req.id} className={`p-4 flex flex-col lg:flex-row lg:items-center gap-3 transition ${focusedRequestId===req.id?'bg-[#eef6f1] ring-2 ring-inset ring-[#2F6555]/20':''}`}><div className="flex-1 min-w-0"><div className="font-black text-sm">{req.displayName}</div><div dir="ltr" className="text-[11px] text-[#656b66] break-all">{req.email}</div><div className="mt-2 flex flex-wrap gap-2"><Badge variant={req.status==='PENDING'?'amber':req.status==='ISSUED'?'emerald':'neutral'}>{resetStatus(req.status,ar)}</Badge><Badge variant="neutral">{req.reviewerRole==='super_admin'?(ar?'اعتماد السوبر أدمن':'Platform owner approval'):req.reviewerRole==='operator_owner'?(ar?'اعتماد مالك المشغّل':'Operator owner approval'):(ar?'اعتماد مدير الجهة':'Organization admin approval')}</Badge></div><div className="text-[10px] text-[#656b66] mt-2">{ar?`طُلب في ${dateText(req.requestedAt,ar)}`:`Requested ${dateText(req.requestedAt,ar)}`}</div></div>{(req.status==='PENDING'||req.status==='ISSUED')&&<div className="flex flex-wrap gap-2"><Button disabled={issuingReset===req.id} onClick={()=>void issuePasswordReset(req)} icon={<QrCode className="w-4 h-4"/>}>{issuingReset===req.id?'…':(req.status==='ISSUED'?(ar?'إنشاء رابط جديد':'Create new link'):(ar?'إنشاء الرابط وQR':'Create link & QR'))}</Button><Button variant="danger" onClick={()=>setConfirm({kind:'cancel-reset',reset:req,reason:ar?'إلغاء طلب تغيير كلمة المرور بناءً على قرار المسؤول':'Cancel password reset request by authorized administrator'})} icon={<XCircle className="w-4 h-4"/>}>{ar?'إلغاء الطلب':'Cancel request'}</Button></div>}</div>)}{!passwordResetRequests.length&&<div className="py-10 text-center text-xs text-[#696f6b]">{operatorScoped?(ar?'لا توجد طلبات تغيير كلمة مرور لهذا المشغّل.':'No password reset requests for this operator.'):(ar?'لا توجد طلبات تغيير كلمة مرور لهذه الجهة.':'No password reset requests for this organization.')}</div>}</div></div>
  </div>}

  {tab==='invite'&&<div className="mt-4 space-y-3">
   <div className="rounded-2xl border border-[#d7e1dc] bg-[#f7faf8] p-4"><div className="flex items-start gap-3"><ShieldCheck className="w-5 h-5 text-[#2F6555] shrink-0 mt-0.5"/><div><div className="text-sm font-black">{operatorScoped?(ar?'إضافة مستخدم للمشغّل':'Add operator user'):(ar?'إضافة حساب إداري':'Add administrative account')}</div><p className="text-[11px] leading-6 text-[#5d645f] mt-1">{ar?'بعد الإضافة سيظهر الحساب فورًا في «الفريق والصلاحيات» بحالة «بانتظار التفعيل»، ويمكنك تعديل الدعوة أو إلغاؤها قبل استخدام QR.':'The invited account remains visible and editable until activation.'}</p></div></div></div>
   <div className="rounded-2xl border border-[#dfddd6] p-4"><div className="flex items-center gap-2"><UserPlus className="w-4 h-4 text-[#2F6555]"/><div className="text-sm font-black">{ar?'بيانات المستخدم':'User details'}</div></div><div className="grid sm:grid-cols-2 gap-3 mt-4"><label className="block"><span className="mizan-field-label">{ar?'الاسم الحقيقي':'Display name'}</span><input disabled={identityProvisioningLocked} autoFocus lang={ar?'ar':'en'} data-mizan-kind={ar?'arabic':'latin'} value={name} onChange={e=>setName(e.target.value)} className="mizan-input disabled:opacity-50" placeholder={ar?'الاسم الحقيقي':'Display name'}/></label><label className="block"><span className="mizan-field-label">{ar?'البريد الإلكتروني':'Email'}</span><input disabled={identityProvisioningLocked} type="email" dir="ltr" value={email} onChange={e=>setEmail(e.target.value)} className="mizan-input disabled:opacity-50" placeholder="name@example.com"/></label><label className="sm:col-span-2 block"><span className="mizan-field-label">{ar?'الدور':'Role'}</span><select disabled={identityProvisioningLocked} value={role} onChange={e=>setRole(e.target.value as Role|'')} className="mizan-input disabled:opacity-50"><option value="" disabled>{ar?'اختر الدور':'Choose role'}</option>{effectiveRoles.map(r=><option key={r} value={r}>{ar?arRole(r):r.replaceAll('_',' ')}</option>)}</select>{role&&roleHint(role,ar)&&<span className="mt-1.5 block text-[10px] leading-5 text-[#69706b]">{roleHint(role,ar)}</span>}</label></div><Button className="mt-3" disabled={identityProvisioningLocked||!isEmail(email)||!name.trim()||!role||(competitionClosed&&role!=='auditor')} onClick={()=>void create()} icon={<KeyRound className="w-4 h-4"/>}>{ar?'إضافة المستخدم وإنشاء QR':'Add user & create QR'}</Button>
    {oneTimeToken&&<div className="mt-4 rounded-2xl border border-[#d9e4de] bg-[#F7FAF8] p-4"><div className="flex items-center gap-2 text-[#214C40]"><QrCode className="w-4 h-4"/><div className="text-xs font-black">{ar?`QR تفعيل لمرة واحدة${oneTimeLabel?` · ${oneTimeLabel}`:''}`:`One-time activation QR${oneTimeLabel?` · ${oneTimeLabel}`:''}`}</div></div><div className="mt-4 flex justify-center"><div className="rounded-2xl bg-white p-3 border"><RealQRCode value={qrValue} size={184}/></div></div><button onClick={()=>void copyActivation()} className="mt-3 mx-auto min-h-11 px-3 rounded-xl flex items-center gap-2 text-xs font-bold text-[#214C40]"><Copy className="w-4 h-4"/>{ar?'نسخ رابط التفعيل':'Copy activation link'}</button></div>}
   </div>
  </div>}

  {tab==='sessions'&&<div className="mt-4 rounded-2xl border border-[#dfddd6] overflow-hidden"><div className="px-4 py-3 bg-[#faf9f5] border-b border-[#e5e3dc]"><div className="flex items-center gap-2"><Laptop2 className="w-4 h-4 text-[#2F6555]"/><div className="text-sm font-black">{ar?'الجلسات النشطة الآن':'Active sessions'}</div></div><p className="text-[10px] leading-5 text-[#656b66] mt-1">{ar?'يمكن إغلاق جلسات الصلاحية المحددة هنا، أو إغلاق كل جلسات الحساب من بطاقة المستخدم في «الفريق والصلاحيات».':'Revoke scoped sessions here, or close every account session from the Team & grants tab.'}</p></div><div className="p-3 grid sm:grid-cols-2 xl:grid-cols-3 gap-3 items-start">{activeSessions.map((x:any)=>{const a=accountForSession(x),g=grantForSession(x),open=openSessionId===x.id;return <div key={x.id} className={`rounded-2xl border p-4 flex flex-col gap-3 ${open?'border-[#b9ccc3] bg-[#F7FAF8] sm:col-span-2 xl:col-span-3':'border-[#e5e3dc] bg-white'}`}><div className="flex-1 min-w-0"><button type="button" onClick={()=>setOpenSessionId(open?'':x.id)} aria-expanded={open} className="w-full flex items-center justify-between gap-2 text-start"><span className="text-sm font-black truncate">{a?.displayName||arRole(x.role)}</span><ChevronDown className={`w-4 h-4 shrink-0 text-[#66706a] transition ${open?'rotate-180':''}`}/></button>{open&&<div className="text-[11px] text-[#656b66] mt-2 break-all" dir="ltr">{x.deviceName||x.deviceId}</div>}<div className="mt-2 flex flex-wrap gap-2"><Badge variant="emerald">{ar?arRole(x.role):String(x.role||'').replaceAll('_',' ')}</Badge><Badge variant="neutral">{x.authenticationAssurance==='MFA'?(ar?'تحقق بخطوتين':'MFA'):(ar?'تحقق أحادي':'Single factor')}</Badge></div></div><div className="text-[10px] text-[#656b66] sm:text-end"><div>{ar?'آخر نشاط':'Last seen'}</div><div className="font-bold mt-1">{dateText(x.lastSeenAt,ar)}</div></div>{g&&<IconButton title={ar?'إغلاق جلسات هذه الصلاحية':'Revoke scoped sessions'} onClick={()=>void revokeGrantSessions(g)}><Laptop2 className="w-4 h-4"/></IconButton>}</div>})}{!activeSessions.length&&<div className="py-10 text-center text-xs text-[#696f6b]">{ar?'لا توجد جلسات نشطة في هذا النطاق.':'No active sessions in this scope.'}</div>}</div></div>}

  <Modal isOpen={!!editInvitation} onClose={()=>setEditInvitation(null)} title={ar?'تعديل الدعوة قبل التفعيل':'Edit pending invitation'} subtitle={ar?'تغيير البريد هنا آمن لأنه لم يُربط بعد بحساب Firebase مفعّل.':'The identity is not activated yet, so the invitation email can still be corrected.'}>
   <div className="space-y-3"><label className="block"><span className="mizan-field-label">{ar?'الاسم':'Name'}</span><input className="mizan-input" value={editInvitationName} onChange={e=>setEditInvitationName(e.target.value)}/></label><label className="block"><span className="mizan-field-label">{ar?'البريد':'Email'}</span><input className="mizan-input" type="email" dir="ltr" value={editInvitationEmail} onChange={e=>setEditInvitationEmail(e.target.value)}/></label><label className="block"><span className="mizan-field-label">{ar?'الدور':'Role'}</span><select className="mizan-input" value={editInvitationRole} onChange={e=>setEditInvitationRole(e.target.value as Role)}>{[...new Set([editInvitation?.requestedRole,...effectiveRoles].filter(Boolean))].map(r=><option key={String(r)} value={String(r)}>{arRole(String(r))}</option>)}</select></label><div className="flex justify-end gap-2"><Button variant="ghost" onClick={()=>setEditInvitation(null)}>{ar?'تراجع':'Cancel'}</Button><Button loading={busyAction===`inv-edit-${editInvitation?.id}`} disabled={!normalizeSpaces(editInvitationName)||!isEmail(editInvitationEmail)||!editInvitationRole} onClick={()=>void saveInvitation()}>{ar?'حفظ التعديل':'Save changes'}</Button></div></div>
  </Modal>

  <Modal isOpen={!!editAccount} onClose={()=>setEditAccount(null)} title={ar?'تعديل بيانات الحساب':'Edit account details'} subtitle={ar?'البريد بعد التفعيل مرتبط بهوية تسجيل الدخول، لذلك لا يُغيَّر من سجل الصلاحيات وحده. يمكنك تعديل الاسم وإدارة الدور من بطاقة الصلاحية.':'After activation, email is bound to the sign-in identity. Edit the display name here and roles from the scoped grant.'}>
   <div className="space-y-3"><label className="block"><span className="mizan-field-label">{ar?'الاسم':'Name'}</span><input className="mizan-input" value={editAccountName} onChange={e=>setEditAccountName(e.target.value)}/></label><label className="block"><span className="mizan-field-label">{ar?'بريد تسجيل الدخول':'Sign-in email'}</span><input className="mizan-input opacity-70" dir="ltr" value={editAccount?.email||''} readOnly/></label><div className="flex justify-end gap-2"><Button variant="ghost" onClick={()=>setEditAccount(null)}>{ar?'تراجع':'Cancel'}</Button><Button loading={busyAction===`account-edit-${editAccount?.id}`} disabled={!normalizeSpaces(editAccountName)} onClick={()=>void saveAccount()}>{ar?'حفظ':'Save'}</Button></div></div>
  </Modal>

  <Modal isOpen={!!editGrant} onClose={()=>setEditGrant(null)} title={ar?'تعديل الدور والصلاحية':'Edit role & grant'} subtitle={ar?'تغيير الدور يغلق الجلسات النشطة المرتبطة بهذا النطاق حتى يُعاد الدخول بالصلاحية الجديدة.':'Changing role revokes active sessions in this scope so the new authority is applied cleanly.'}>
   <div className="space-y-3"><div className="rounded-xl bg-[#f3f1eb] p-3"><div className="text-xs font-black">{editGrant?.account?.displayName}</div><div className="text-[10px] text-[#656b66] mt-1" dir="ltr">{editGrant?.account?.email}</div></div><label className="block"><span className="mizan-field-label">{ar?'الدور الجديد':'New role'}</span><select className="mizan-input" value={editGrantRole} onChange={e=>setEditGrantRole(e.target.value as Role)}>{editGrant&&roleChoicesForGrant(editGrant.grant).map(r=><option key={r} value={r}>{ar?arRole(r):r.replaceAll('_',' ')}</option>)}</select></label><div className="flex justify-end gap-2"><Button variant="ghost" onClick={()=>setEditGrant(null)}>{ar?'تراجع':'Cancel'}</Button><Button loading={busyAction===`grant-edit-${editGrant?.grant?.id}`} disabled={!editGrantRole||editGrantRole===editGrant?.grant?.role} onClick={()=>void saveGrant()}>{ar?'تحديث الدور':'Update role'}</Button></div></div>
  </Modal>

  <Modal isOpen={!!confirm} onClose={()=>setConfirm(null)} title={confirmTitle} subtitle={confirm?.kind==='delete-account'?(ar?'الحذف هنا إلغاء وصول تدقيقي: لا نمحو التاريخ، لكن الحساب والصلاحيات والجلسات تتوقف فورًا.':'Access is removed immediately while audit history is retained.'):undefined}>
   {confirm&&<div className="space-y-4"><div className="rounded-xl bg-[#f7f5ef] p-3 text-xs leading-6 text-[#555e58]">{confirm.account?.displayName||confirm.invitation?.displayName||confirm.reset?.displayName||(ar?'الصلاحية المحددة':'Selected grant')}</div><label className="block"><span className="mizan-field-label">{ar?'سبب الإجراء':'Reason'}</span><textarea rows={3} className="mizan-input resize-none" value={confirm.reason} onChange={e=>setConfirm({...confirm,reason:e.target.value})}/><span className="mt-1 block text-[9px] text-[#656b66]">{ar?'يُحفظ السبب في سجل التدقيق لهذا الإجراء.':'The reason is retained in the audit trail.'}</span></label><div className="flex justify-end gap-2"><Button variant="ghost" onClick={()=>setConfirm(null)}>{ar?'تراجع':'Cancel'}</Button><Button variant={confirm.kind.startsWith('delete')||confirm.kind==='cancel-reset'||confirm.kind==='suspend-account'?'danger':'primary'} loading={busyAction===`confirm-${confirm.kind}`} disabled={confirm.reason.trim().length<5} onClick={()=>void runConfirm()}>{ar?'تأكيد الإجراء':'Confirm action'}</Button></div></div>}
  </Modal>
 </section>;
};

const IconButton=({title,onClick,children,danger=false}:{title:string;onClick:()=>void;children:React.ReactNode;danger?:boolean})=><button type="button" title={title} aria-label={title} onClick={onClick} className={`w-11 h-11 rounded-xl border grid place-items-center transition ${danger?'text-[#94564d] border-[#ead9d5] hover:bg-[#f7ece9]':'text-[#214C40] border-[#d9dfdb] hover:bg-white'}`}>{children}</button>;
